// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.rule.registryimport com.roshan.persona.brain.rule.BrainRuleimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Rule registry. * * Collects all [BrainRule]s from three sources: *   1. Compiled rules (Hilt multibinding — @Rule-annotated classes) *   2. User rules (Room `user_rules` table — populated via NL automation) *   3. Imported rules (JSON files — one-time import to Room) * * For Module 2, only source #1 (Hilt multibinding) is wired. Sources #2 and #3 * are added when :feature:memory (Module 3) ships the user_rules table. * * Rules are sorted by priority on first access and cached. Cache is invalidated * when user rules change (via [refresh]). * * @see <a href="docs/spec/module2-spec-review.pdf">§5.1 Rule Storage</a> */@Singletonclass RuleRegistry @Inject constructor(    /** Compiled rules from Hilt multibinding. */    private val compiledRules: Set<@JvmSuppressWildcards BrainRule>,) {    @Volatile    private var cachedRules: List<BrainRule>? = null    /** User rules (added dynamically — empty for Module 2, populated by Module 8). */    @Volatile    private var userRules: List<BrainRule> = emptyList()    /**     * Get all active rules, sorted by priority (lower = higher priority).     * Only enabled rules are returned.     */    fun getActiveRules(): List<BrainRule> {        cachedRules?.let { return it }        val all = (compiledRules + userRules)            .filter { it.isEnabled }            .sortedWith(                compareBy<BrainRule> { it.priority }                    .thenBy { it.id }  // deterministic tiebreak            )        cachedRules = all        Timber.tag("NOUS.L1").v("RuleRegistry: ${all.size} active rules (${compiledRules.size} compiled, ${userRules.size} user)")        return all    }    /** Find a rule by ID. */    fun findById(ruleId: String): BrainRule? =        getActiveRules().firstOrNull { it.id == ruleId }    /** Find all rules with a specific tag. */    fun findByTag(tag: String): List<BrainRule> =        getActiveRules().filter { tag in it.tags }    /** Find all rules matching an intent type. */    fun findByIntentType(intentType: kotlin.reflect.KClass<out com.roshan.persona.brain.intent.Intent>): List<BrainRule> =        getActiveRules().filter { rule ->            when (val cond = rule.condition) {                is com.roshan.persona.brain.rule.RuleCondition.IntentIs -> cond.intent == intentType                else -> false  // complex conditions checked at runtime            }        }    /**     * Add a user rule dynamically (called by NL automation in Module 8).     * If a rule with the same ID exists, it is replaced.     * Invalidates cache so next access re-sorts.     */    fun addUserRule(rule: BrainRule) {        // Remove existing rule with same ID first (from either user rules or compiled rules)        userRules = userRules.filterNot { it.id == rule.id } + rule        cachedRules = null        Timber.tag("NOUS.L1").i("User rule added: ${rule.id}")    }    /**     * Remove a user rule by ID.     */    fun removeUserRule(ruleId: String): Boolean {        val before = userRules.size        userRules = userRules.filterNot { it.id == ruleId }        val removed = userRules.size < before        if (removed) {            cachedRules = null            Timber.tag("NOUS.L1").i("User rule removed: $ruleId")        }        return removed    }    /**     * Refresh cache (called when user rules change in Room).     */    fun refresh() {        cachedRules = null    }    /** Total rule count (for debugging). */    fun count(): Int = getActiveRules().size}
